//! The chain's time-driven rules, ported exactly.
//!
//! Every function here answers a question the chain answers inside a
//! transaction, with the chain's arithmetic, and cites the Go it mirrors.
//! Nothing here reads a clock, a cache or the network: given the same inputs
//! it returns what a validator would. `golden/difficulty.json` (generated by
//! `scripts/mirror_golden.sh` from the chain's own `work.go`) pins it.
//!
//! **Which height?** Every rule takes the height the transaction EXECUTES at
//! (`ctx.BlockHeight()` in the keeper). A client that has seen committed tip
//! `h` cannot land a transaction before `h + 1`, so a question asked "now"
//! is answered at [`earliest_execution`]`(tip)`, never at `tip` itself.

/// The rule set these functions mirror. Bump with every chain upgrade that
/// touches them, and regenerate the golden vectors.
pub const RULES: &str = "structsd v0.22.0";

/// Blocks between the newest committed height a client has observed and the
/// first height a transaction it signs now can execute at.
pub const INCLUSION_LAG: u64 = 1;

/// Hex zeros a proof needs at the start, and the floor once work fully ages.
pub const MAX_DIFFICULTY: u64 = 64;
pub const MIN_DIFFICULTY: u64 = 1;

/// The first height a transaction signed against committed tip `tip` can
/// execute at.
pub fn earliest_execution(tip: u64) -> u64 {
    tip.saturating_add(INCLUSION_LAG)
}

/// `types.CalculateDifficulty` (x/structs/types/work.go): the leading hex
/// zeros a proof of work aged `age` blocks must carry against `range`.
/// The integer port lives with the hasher; this is the same function.
pub fn difficulty(age: u64, range: u64) -> u64 {
    crate::hasher::difficulty::calculate_difficulty(age, range)
}

/// Age of work anchored at `start` when executed at `height`, as the
/// completion handlers compute it (`currentAge := blockHeight - blockStart`
/// after `if blockHeight < blockStart` refuses: msg_server_struct_build_complete.go,
/// msg_server_struct_ore_miner_complete.go, msg_server_struct_ore_refinery_complete.go,
/// msg_server_planet_raid_complete.go). `None` is the chain's refusal.
pub fn work_age(height: u64, start: u64) -> Option<u64> {
    height.checked_sub(start)
}

/// A player's charge at `height`: `BlockHeight - lastAction`
/// (`PlayerCache.GetCharge`, keeper/player_cache.go). The chain subtracts
/// unsigned; a lastAction ahead of the height cannot occur on-chain, so it
/// saturates here rather than wrapping.
pub fn charge(height: u64, last_action: u64) -> u64 {
    height.saturating_sub(last_action)
}

/// The first height at which a player with `last_action` holds `need` charge.
pub fn charge_height(last_action: u64, need: u64) -> u64 {
    last_action.saturating_add(need)
}

/// The smallest work age at which a proof needs at most `target` zeros
/// against `range` — the exact inverse of [`difficulty`].
///
/// The curve is non-increasing in age, so this is a binary search over the
/// integer rule itself: no logarithms, no float inverse to disagree with the
/// chain at a boundary. `None` when no age gets there (target 0, or a range
/// of 0/1, which the chain pins at 64 forever).
pub fn ready_age(range: u64, target: u64) -> Option<u64> {
    if target >= MAX_DIFFICULTY {
        return Some(0);
    }
    if target < MIN_DIFFICULTY || range <= 1 {
        return None;
    }
    // Ages 0 and 1 are pinned at 64; at age == range the exponent is 63 and
    // the difficulty is 1, so the answer lies in [2, range].
    let (mut lo, mut hi) = (2u64, range.max(2));
    if difficulty(hi, range) > target {
        return None;
    }
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if difficulty(mid, range) <= target {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    Some(lo)
}

/// The first height at which work anchored at `start` against `range` can be
/// completed with a proof of at most `target` zeros.
pub fn ready_height(start: u64, range: u64, target: u64) -> Option<u64> {
    ready_age(range, target).and_then(|a| start.checked_add(a))
}

/// Messages that DISCHARGE the player — every handler that checks
/// `GetCharge()` and then calls `PlayerCache.Discharge()` (lastAction :=
/// block height): msg_server_struct_{activate, attack, build_initiate,
/// defense_set, defense_clear, move, stealth_activate, stealth_deactivate,
/// trash}.go. `MsgFleetMove`, `MsgStructDeactivate` and the proof
/// completions neither check nor spend charge.
pub const DISCHARGING: &[&str] = &[
    "MsgStructActivate",
    "MsgStructAttack",
    "MsgStructBuildInitiate",
    "MsgStructDefenseSet",
    "MsgStructDefenseClear",
    "MsgStructMove",
    "MsgStructStealthActivate",
    "MsgStructStealthDeactivate",
    "MsgStructTrash",
];

/// Does a message of this type URL (or bare name) spend the player's charge?
pub fn discharges(type_url: &str) -> bool {
    let name = type_url.rsplit('.').next().unwrap_or(type_url);
    DISCHARGING.contains(&name)
}

/// What a completion's proof hashes (`hashInput` in the four completion
/// handlers): `{struct}MINE{anchor}NONCE{nonce}`, `…REFINE…`, `…BUILD…`, and
/// for a raid `{fleet}@{planet}RAID{anchor}NONCE{nonce}`.
pub fn proof_input(kind: crate::mcp::types::TaskType, object_id: &str, raid_planet: Option<&str>, anchor: u64, nonce: &str) -> String {
    use crate::mcp::types::TaskType;
    match kind {
        TaskType::Mine => format!("{object_id}MINE{anchor}NONCE{nonce}"),
        TaskType::Refine => format!("{object_id}REFINE{anchor}NONCE{nonce}"),
        TaskType::Build => format!("{object_id}BUILD{anchor}NONCE{nonce}"),
        TaskType::Raid => format!("{object_id}@{}RAID{anchor}NONCE{nonce}", raid_planet.unwrap_or("")),
    }
}

/// `types.HashBuild`: lowercase hex SHA-256 of the input.
pub fn hash_build(input: &str) -> String {
    use sha2::{Digest, Sha256};
    hex::encode(Sha256::digest(input.as_bytes()))
}

/// Leading hex zeros of a hash string.
pub fn leading_zeros(hash: &str) -> u64 {
    hash.bytes().take_while(|b| *b == b'0').count() as u64
}

/// `types.HashBuildAndCheckDifficulty`: the proof must BE the input's hash and
/// carry at least `difficulty(age, range)` leading zeros. Returns the chain's
/// `(valid, achieved)` — `achieved` counts zeros only up to the requirement,
/// stopping at the first non-zero, exactly as the Go loop does.
pub fn proof_accepted(input: &str, proof: &str, age: u64, range: u64) -> (bool, u64) {
    if hash_build(input) != proof {
        return (false, 0);
    }
    let need = difficulty(age, range);
    let zeros = leading_zeros(proof);
    if zeros >= need {
        (true, need)
    } else {
        (false, zeros)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Deserialize;

    #[derive(Deserialize)]
    struct Inverse {
        range: u64,
        ready_age: Vec<Option<u64>>,
    }

    #[derive(Deserialize)]
    struct Golden {
        source: String,
        difficulty: Vec<[u64; 3]>,
        inverse: Vec<Inverse>,
    }

    fn golden() -> Golden {
        serde_json::from_str(include_str!("golden/difficulty.json")).expect("golden vectors parse")
    }

    #[test]
    fn golden_vectors_come_from_the_rules_this_module_claims() {
        let g = golden();
        let claimed = RULES.trim_start_matches("structsd ");
        assert!(
            g.source.contains(claimed),
            "golden vectors were generated from `{}` but RULES says `{}` — rerun scripts/mirror_golden.sh",
            g.source,
            RULES
        );
    }

    #[test]
    fn difficulty_matches_the_chain_on_every_golden_case() {
        let g = golden();
        assert!(g.difficulty.len() > 5000, "golden set is suspiciously small");
        for [age, range, want] in g.difficulty {
            assert_eq!(difficulty(age, range), want, "difficulty(age={age}, range={range})");
        }
    }

    #[test]
    fn ready_age_is_the_exact_inverse_found_by_the_chain_scan() {
        for row in golden().inverse {
            for (i, want) in row.ready_age.iter().enumerate() {
                let target = i as u64 + 1;
                assert_eq!(ready_age(row.range, target), *want, "ready_age(range={}, target={target})", row.range);
            }
        }
    }

    #[derive(Deserialize)]
    struct ProofCase {
        input: String,
        proof: String,
        age: u64,
        range: u64,
        valid: bool,
        achieved: u64,
    }

    #[test]
    fn proof_acceptance_matches_the_chain() {
        #[derive(Deserialize)]
        struct G {
            proofs: Vec<ProofCase>,
        }
        let g: G = serde_json::from_str(include_str!("golden/difficulty.json")).unwrap();
        assert!(g.proofs.len() > 100);
        for c in g.proofs {
            assert_eq!(proof_accepted(&c.input, &c.proof, c.age, c.range), (c.valid, c.achieved), "{} age {} range {}", c.input, c.age, c.range);
        }
    }

    #[test]
    fn the_discharge_list_is_the_chains() {
        assert!(discharges("/structs.structs.MsgStructAttack"));
        assert!(discharges("/structs.structs.MsgStructStealthDeactivate"));
        assert!(discharges("MsgStructTrash"));
        assert!(!discharges("/structs.structs.MsgFleetMove"), "fleet move neither checks nor spends charge");
        assert!(!discharges("/structs.structs.MsgStructOreMinerComplete"));
        assert!(!discharges("/structs.structs.MsgStructDeactivate"));
    }

    #[test]
    fn target_zero_is_never_reachable() {
        assert_eq!(ready_age(28_000, 0), None);
    }

    #[test]
    fn a_transaction_seen_at_tip_executes_one_block_later() {
        assert_eq!(earliest_execution(100), 101);
        // Charge observed at the tip understates what the chain will count.
        assert_eq!(charge(earliest_execution(100), 90), 11);
    }

    #[test]
    fn a_future_anchor_is_refused_like_the_chain_refuses_it() {
        assert_eq!(work_age(99, 100), None);
        assert_eq!(work_age(100, 100), Some(0));
    }

    #[test]
    fn charge_height_inverts_charge() {
        for last in [0u64, 7, 1_000_000] {
            for need in [0u64, 1, 5, 300] {
                assert_eq!(charge(charge_height(last, need), last), need);
            }
        }
    }
}
